class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout
        self retries = 0
        self.backoff = 0

    def get(self, path):
        try:
            response = urllib.request.urlopen((self.base_url + path), timeout=self.timeout)
            return response.read().decode('utf-8')
        except urllib.error.URLError as e:
            self.retries += 1
            if self.retries > 3:
                raise ConnectionError("Failed to connect due to excessive retries")
            self.backoff = 0.5 * (2 ** (self.retries - 1))
            self.retries += 1
            try:
                response = urllib.request.urlopen((self.base_url + path), timeout=self.timeout)
                return response.read().decode('utf-8')
            except urllib.error.URLError as e:
                self.retries += 1
                if self.retries > 3:
                    raise ConnectionError("Failed to connect due to excessive retries")
                self.backoff = 1.0 * (2 ** (self.retries - 1))
                self.retries += 1
                if self.backoff > 2:
                    raise ConnectionError("Failed to connect due to excessive retries")
        except urllib.error.HTTPError as e:
            if e.code == 429:
                self.retries += 1
                if self.retries > 3:
                    raise RateLimitError("Rate limit exceeded after 3 retries")
                self.backoff = 0.5 * (2 ** (self.retries - 1))
                self.retries += 1
                try:
                    response = urllib.request.urlopen((self.base_url + path), timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.URLError as e:
                    self.retries += 1
                    if self.retries > 3:
                        raise ConnectionError("Failed to connect due to excessive retries")
                    self.backoff = 1.0 * (2 ** (self.retries - 1))
                    self.retries += 1
                    if self.backoff > 2:
                        raise ConnectionError("Failed to connect due to excessive retries")
            elif e.code == 5xx:
                self.retries += 1
                if self.retries > 1:
                    raise ServerError("Server error after 1 retry")
                self.backoff = 1.0 * (2 ** (self.retries - 1))
                self.retries += 1
                if self.backoff > 1:
                    raise ServerError("Server error after 1 retry")
        except Exception as e:
            raise ClientError("An error occurred: " + str(e))

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass
